<?php declare(strict_types=1); require __DIR__.'/admin-empresa-action-common.php'; admin_empresa_post(); [$app,$session,$user]=admin_empresa_context(); try{$id=filter_var($_POST['empresa_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!is_int($id))throw new InvalidArgumentException('Empresa inválida.');$app->companyAdmin()->enter($id,$user->id(),isset($_POST['motivo'])?(string)$_POST['motivo']:null,(string)($_SERVER['REMOTE_ADDR']??''),(string)($_SERVER['HTTP_USER_AGENT']??''));$session->regenerate();$session->flash('success','Acesso administrativo iniciado.');admin_empresa_redirect($app,'empresa-painel.php');}catch(InvalidArgumentException $e){$session->flash('danger',$e->getMessage());}catch(Throwable $e){error_log('Company support enter failed: '.get_class($e));$session->flash('danger','Não foi possível iniciar o acesso à empresa.');}admin_empresa_redirect($app);
